import { createRoot } from 'react-dom/client';
import { Activity, ArrowDownRight, ArrowRight, ArrowUpRight, Award, BarChart3, Bell, BookOpen, CalendarDays, Check, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, Clock3, Download, FileUp, Filter, GraduationCap, LayoutDashboard, LogOut, Medal, Menu, MoreHorizontal, Pencil, Plus, Search, Settings, Share2, ShieldCheck, Sparkles, Target, Trophy, Users, X, Zap } from 'lucide-react';
